options.customCss:
:root {
  /* =========================
     THE PLATINUM DARK PALETTE
     ========================= */
  --chat--color-bg-main: #0b0f19;       /* Deepest rich midnight canvas */
  --chat--color-bg-surface: #111726;    /* Header & Footer background */
  --chat--color-bg-bubble: #1e2638;     /* Sleek bubble background */

  --chat--color-text-pure: #ffffff;
  --chat--color-text-main: #f1f5f9;     /* Off-white for readability */
  --chat--color-text-muted: #64748b;    /* Clean slate grey for subtext */

  --chat--color-purple-gradient: linear-gradient(135deg, #7c3aed, #6d28d9);
  --chat--color-border: rgba(255, 255, 255, 0.05);
  --chat--font-family: 'Inter', system-ui, -apple-system, sans-serif;
}

/* =========================
   GLOBAL OVERRIDES (Fixes Light Leaks)
   ========================= */
body, 
.chat-window-wrapper,
.chat-window {
  background-color: var(--chat--color-bg-main) !important;
  color: var(--chat--color-text-main);
  font-family: var(--chat--font-family);
}

/* =========================
   CHAT CONTAINER
   ========================= */
.chat-window {
  max-width: 1100px;
  height: 100vh;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  background: var(--chat--color-bg-main);
}

/* =========================
   HEADER (Unified Premium Dark)
   ========================= */
.chat-header {
  padding: 32px 40px;
  background-color: var(--chat--color-bg-surface);
  border-bottom: 1px solid var(--chat--color-border);
}

.chat-heading {
  font-size: 24px;
  font-weight: 700;
  color: var(--chat--color-text-pure);
  margin: 0 0 6px 0;
}

.chat-subtitle {
  font-size: 14px;
  color: var(--chat--color-text-muted);
  margin: 0;
  letter-spacing: -0.1px;
}

/* =========================
   BODY & THE "FIX" FOR THOSE WIDE STRIPS
   ========================= */
.chat-body {
  flex: 1;
  overflow-y: auto;
  padding: 40px;
  background-color: var(--chat--color-bg-main);
  display: flex;
  flex-direction: column;
  gap: 12px; /* Tighter gap for sequential messages */
}

/* CRITICAL FIX: Stop messages from acting like full-width input rows */
.chat-message {
  width: max-content;         /* Shrinks width down to only fit the text */
  max-width: 65%;             /* Prevents long text from clipping */
  min-width: 80px;
  padding: 14px 20px;
  font-size: 15px;
  line-height: 1.6;
  font-weight: 450;
  box-sizing: border-box;
  word-wrap: break-word;
}

/* Bot Messages (The ones seen in your screenshot) */
.chat-message-from-bot {
  margin-right: auto;
  margin-left: 0;
  background-color: var(--chat--color-bg-bubble) !important;
  color: var(--chat--color-text-main) !important;
  border: 1px solid var(--chat--color-border) !important;
  border-radius: 4px 16px 16px 16px !important; /* Asymmetric elegant curve */
}

/* User Messages */
.chat-message-from-user {
  margin-left: auto;
  margin-right: 0;
  background: var(--chat--color-purple-gradient) !important;
  color: var(--chat--color-text-pure) !important;
  border: none !important;
  border-radius: 16px 16px 4px 16px !important;
  box-shadow: 0 4px 12px rgba(124, 58, 237, 0.15);
}

/* =========================
   FOOTER & INPUT REGION
   ========================= */
.chat-footer {
  padding: 24px 40px 32px 40px;
  background-color: var(--chat--color-bg-surface);
  border-top: 1px solid var(--chat--color-border);
  display: flex;
  align-items: center;
  gap: 16px;
}

/* The Input Container Framework */
.chat-input-container {
  display: flex;
  width: 100%;
  background-color: #080c14; /* Deep inset shade */
  border: 1px solid var(--chat--color-border);
  border-radius: 14px;
  padding: 6px 12px 6px 18px;
  align-items: center;
  transition: all 0.2s ease;
}

.chat-input-container:focus-within {
  border-color: #8b5cf6;
  box-shadow: 0 0 0 4px rgba(139, 92, 246, 0.15);
}

.chat-input-field {
  flex: 1;
  background: transparent !important;
  border: none !important;
  color: var(--chat--color-text-pure) !important;
  font-size: 15px;
  padding: 12px 0 !important;
  outline: none !important;
}

.chat-input-field::placeholder {
  color: var(--chat--color-text-muted) !important;
  opacity: 0.8;
}

/* =========================
   SEND BUTTON (Minimalist & Polished)
   ========================= */
.chat-submit-btn, 
button.send-btn {
  background: var(--chat--color-purple-gradient) !important;
  border: none !important;
  width: 42px;
  height: 42px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.chat-submit-btn:hover,
button.send-btn:hover {
  filter: brightness(1.15);
  transform: scale(1.03);
}

.chat-submit-btn svg,
button.send-btn svg {
  fill: var(--chat--color-text-pure);
  width: 18px;
  height: 18px;
}

/* =========================
   SCROLLBAR
   ========================= */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 99px;
}
::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.2);
}
